<?php
session_start();require_once __DIR__.'/../includes.php';need_login();$msg='';$err='';
if(isset($_GET['logout'])){session_destroy();header('Location:login.php');exit;}
if(isset($_GET['delete'])){$id=$_GET['delete'];$a=get_songs();foreach($a as $k=>$s){if(($s['id']??'')===$id){if(!empty($s['file']))@unlink(__DIR__.'/../'.$s['file']);if(!empty($s['cover']))@unlink(__DIR__.'/../'.$s['cover']);unset($a[$k]);}}save_songs($a);header('Location:index.php');exit;}
if($_SERVER['REQUEST_METHOD']==='POST'){
$title=trim($_POST['title']??'');$dj=trim($_POST['dj']??'DJSTMusic');$cat=trim($_POST['category']??'DJ Remix');
if($title===''||empty($_FILES['song']['name']))$err='Song title aur MP3 file required hai.';
else{$ext=strtolower(pathinfo($_FILES['song']['name'],PATHINFO_EXTENSION));if(!in_array($ext,['mp3','wav','ogg'],true))$err='MP3/WAV/OGG only.';
elseif($_FILES['song']['error']!==UPLOAD_ERR_OK)$err='Upload failed.';
else{$base=preg_replace('/[^a-zA-Z0-9_-]+/','-',pathinfo($_FILES['song']['name'],PATHINFO_FILENAME));$file='uploads/'.date('YmdHis').'-'.$base.'.'.$ext;
if(move_uploaded_file($_FILES['song']['tmp_name'],__DIR__.'/../'.$file)){$cover='';if(!empty($_FILES['cover']['name'])&&$_FILES['cover']['error']===UPLOAD_ERR_OK){$ce=strtolower(pathinfo($_FILES['cover']['name'],PATHINFO_EXTENSION));if(in_array($ce,['jpg','jpeg','png','webp'],true)){$cover='uploads/'.date('YmdHis').'-cover-'.bin2hex(random_bytes(3)).'.'.$ce;move_uploaded_file($_FILES['cover']['tmp_name'],__DIR__.'/../'.$cover);}}$a=get_songs();array_unshift($a,['id'=>bin2hex(random_bytes(6)),'title'=>$title,'dj'=>$dj,'category'=>$cat,'file'=>$file,'cover'=>$cover]);save_songs($a);$msg='Song successfully uploaded!';}else$err='uploads folder writable hona chahiye.';}}
}
$a=get_songs();?>
