<div class="about"><h2>➕ Upload New Song</h2><form method="post" enctype="multipart/form-data"><input name="title" required placeholder="Song title" style="width:100%;padding:13px;margin:7px 0;background:#080808;color:#fff;border:1px solid #400;border-radius:9px"><input name="dj" value="DJSTMusic" placeholder="DJ Name" style="width:100%;padding:13px;margin:7px 0;background:#080808;color:#fff;border:1px solid #400;border-radius:9px"><input name="category" value="DJ Remix" placeholder="Category" style="width:100%;padding:13px;margin:7px 0;background:#080808;color:#fff;border:1px solid #400;border-radius:9px"><p>MP3/WAV/OGG: <input type="file" name="song" accept=".mp3,.wav,.ogg" required></p><p>Cover: <input type="file" name="cover" accept=".jpg,.jpeg,.png,.webp"></p><button style="padding:13px 20px;background:#e00;color:#fff;border:0;border-radius:10px;font-weight:bold">⬆ Upload</button></form></div>
<h2>Uploaded Songs (<?=count($a)?>)</h2><?php foreach($a as $s):?><div class="about" style="padding:15px"><b><?=h($s['title'])?></b><br><small><?=h($s['dj'])?> • <?=h($s['category'])?></small><br><a href="?delete=<?=h($s['id'])?>" onclick="return confirm('Delete this song?')" style="color:#f33">🗑 Delete</a></div><?php endforeach;?><p><a href="../index.php" style="color:#f33">← Website</a></p></main></body></html>